-- sql/flicker_seed.sql
--
-- Sample flicker readings for trying out the flicker pages. Safe to run more than once
-- (it deletes its own previous rows first, by title prefix "[sample] ").
--
-- BEFORE RUNNING: set @email to the account you log in with. The first three
-- readings are attached to that account's most recent report (so the report page's
-- flicker section has something to compare); the rest are standalone.
--
-- The waveform values are synthetic (400 raw samples, like the meter sends); the
-- frequency / percent / index columns are computed from them.

SET @email = 'you@example.com';
SET @uid   = (SELECT id FROM users WHERE email = @email);
SET @rid   = (SELECT id FROM reports WHERE user_id = @uid ORDER BY id DESC LIMIT 1);

-- Make sure the table exists (the site also creates it on first use).
CREATE TABLE IF NOT EXISTS flicker_readings (
  id              INT AUTO_INCREMENT PRIMARY KEY,
  user_id         INT NOT NULL,
  report_id       INT NULL,
  label           VARCHAR(255) NOT NULL DEFAULT '',
  notes           TEXT,
  model           VARCHAR(255),
  frequency_hz    FLOAT,
  percent_flicker FLOAT,
  flicker_index   FLOAT,
  cycle_ms        FLOAT,
  span_ms         FLOAT NULL,          -- total time the waveform samples span, if known
  waveform        MEDIUMTEXT,          -- JSON array of 400 raw sample values
  settings        TEXT,                -- JSON: gear, sample rate, etc. (optional)
  captured_at     DATETIME NULL,
  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_flicker_user (user_id),
  INDEX idx_flicker_report (report_id),
  FOREIGN KEY (user_id)   REFERENCES users(id)   ON DELETE CASCADE,
  FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM flicker_readings WHERE user_id = @uid AND label LIKE '[sample] %';

